import logging

from fastapi import APIRouter, Query, WebSocket, WebSocketDisconnect
from jose import JWTError, jwt

from app.config import settings
from app.dependencies import ALGORITHM
from app.ws.map_collab import map_collab_manager

logger = logging.getLogger(__name__)
router = APIRouter()


def _username_from_token(token: str) -> str | None:
    try:
        payload = jwt.decode(token, settings.secret_key, algorithms=[ALGORITHM])
        return payload.get("sub")
    except JWTError:
        return None


@router.websocket("/map")
async def map_collaboration_ws(
    websocket: WebSocket,
    token: str = Query(...),
    room: str = Query("default"),
):
    username = _username_from_token(token)
    if not username:
        await websocket.close(code=4001)
        return

    await websocket.accept()
    presence = await map_collab_manager.connect(room, websocket, username)

    try:
        await websocket.send_json({
            "type": "connected",
            "username": username,
            "color": presence.color,
        })
        while True:
            data = await websocket.receive_json()
            await map_collab_manager.handle_message(room, websocket, data)
    except WebSocketDisconnect:
        pass
    except Exception as exc:
        logger.debug("WS map error: %s", exc)
    finally:
        await map_collab_manager.disconnect(room, websocket)


@router.websocket("/vision")
async def vision_stream_ws(
    websocket: WebSocket,
    token: str = Query(...),
    map_layer: str = Query("physical"),
):
    from app.config import settings
    from app.ws.vision_stream import stream_vision_analysis

    if not settings.vision_stream_enabled:
        await websocket.close(code=4003)
        return
    username = _username_from_token(token)
    if not username:
        await websocket.close(code=4001)
        return
    try:
        await stream_vision_analysis(websocket, map_layer)
    except Exception as exc:
        logger.debug("WS vision error: %s", exc)
        await websocket.close(code=1011)

