"""Chatbot de produto SentinelAI — responde sobre o sistema (não só NOC)."""

from __future__ import annotations

from sqlalchemy.orm import Session

from app.config import settings
from app.engines.ai.llm_client import chat_completion_messages, llm_available, resolve_llm_config
from app.engines.ai.noc_copilot import build_noc_context
from app.engines.ai.product_knowledge import build_knowledge_corpus, search_knowledge


def _rules_product_reply(message: str, snippets: list[str]) -> tuple[str, list[str]]:
    msg = message.lower()
    if any(w in msg for w in ("login", "senha", "password", "entrar")):
        return (
            "O login é feito em **Usuários** / tela de autenticação com a conta criada no ambiente. "
            "Em desenvolvimento as credenciais ficam no `.env` (`ADMIN_USERNAME` / `ADMIN_PASSWORD`) — "
            "nunca compartilhe senhas em chat. Em produção, senhas fracas são bloqueadas (`APP_ENV`). "
            "LDAP pode ser ativado via configuração. Ver também `docs/LLM-DEEPSEEK-OLLAMA.md` para IA.",
            ["Abrir NOC Copilot", "Ver Dashboard", "Usuários"],
        )
    if any(w in msg for w in ("zion", "zabbix")):
        return (
            "O módulo **Zion** (menu lateral) oferece visão estilo Zabbix: discovery, inventário corporativo, "
            "templates, monitoramento, mapa, eventos, protocolos (WinRM/Modbus/MQTT/IPMI/Telnet/NTP) e IA. "
            "API em `/api/zion/*`.",
            ["Abrir Zion", "Discovery", "Templates"],
        )
    if any(w in msg for w in ("mapa", "topolog", "dude", "canvas")):
        return (
            "O **Mapa de Rede** é o editor visual (estilo The Dude): canvas infinito, drag-drop, undo/redo, "
            "camadas, 2D/3D, animações de tráfego e exportação. Acesse pelo menu Mapa de Rede.",
            ["Abrir Mapa", "Scanner", "Discovery"],
        )
    if any(w in msg for w in ("deepseek", "llm", "ia", "openai", "ollama", "chatbot", "copilot")):
        return (
            "A IA usa API OpenAI-compatible. Recomendado: **DeepSeek** (https://github.com/deepseek-ai). "
            "Configure `COPILOT_LLM_ENABLED=true`, `COPILOT_LLM_PROVIDER=deepseek`, chave e modelo "
            "`deepseek-chat`. Ollama local: provider `ollama` + modelo `deepseek-r1`. "
            "NOC Copilot = operações; Chatbot = ajuda do produto.",
            ["NOC Copilot", "Configurar .env", "Status IA"],
        )
    if snippets:
        body = "Com base no inventário do SentinelAI:\n" + "\n".join(f"• {s}" for s in snippets[:6])
        return body, ["Dashboard", "Zion", "NOC Copilot"]
    return (
        "Sou o Chatbot SentinelAI. Posso explicar módulos (Mapa, Discovery, Alertas, Zion, Plataforma), "
        "como configurar DeepSeek/Ollama e caminhos no menu. Pergunte, por exemplo: "
        "\"como faço discovery SNMP?\" ou \"o que o Zion faz?\".",
        ["O que é Zion?", "Como configurar DeepSeek?", "Mapa de Rede"],
    )


def build_chatbot_system_prompt(noc_ctx: dict | None, snippets: list[str]) -> str:
    cfg = resolve_llm_config()
    knowledge = build_knowledge_corpus()
    # Limita tamanho do prompt; snippets priorizam a pergunta
    if len(knowledge) > 12000:
        knowledge = knowledge[:12000] + "\n…(truncado)"
    snippet_block = "\n".join(f"- {s}" for s in snippets) or "- (nenhum trecho específico)"
    live = ""
    if noc_ctx:
        live = (
            f"\nEstado live (opcional):\n"
            f"- devices={noc_ctx.get('devices_total')} offline={noc_ctx.get('devices_offline')} "
            f"alertas={noc_ctx.get('pending_alerts')} anomalias={noc_ctx.get('active_anomalies')}\n"
        )
    return f"""Você é o Chatbot oficial do SentinelAI — especialista no produto (NMS + Map Editor).
Motor: {cfg['provider']} / modelo {cfg['model']} (ecossistema DeepSeek open-source: https://github.com/deepseek-ai).
Responda em português, claro e objetivo. Cite o caminho do menu quando ensinar a usar algo.
Não invente features que não estejam na base de conhecimento abaixo.
Se a pergunta for operacional (quantos offline?), use o estado live se existir; senão oriente a usar o NOC Copilot.

Trechos relevantes à pergunta:
{snippet_block}
{live}
--- BASE DE CONHECIMENTO ---
{knowledge}
"""


def chatbot_reply(
    session: Session,
    user_message: str,
    *,
    history: list[dict[str, str]] | None = None,
    include_live: bool = True,
) -> dict:
    snippets = search_knowledge(user_message)
    noc_ctx = build_noc_context(session) if include_live else None
    source = "rules-engine"
    answer = None

    if llm_available():
        messages: list[dict[str, str]] = [
            {"role": "system", "content": build_chatbot_system_prompt(noc_ctx, snippets)},
        ]
        for turn in (history or [])[-8:]:
            role = turn.get("role")
            content = (turn.get("content") or "").strip()
            if role in ("user", "assistant") and content:
                messages.append({"role": role, "content": content[:2000]})
        messages.append({"role": "user", "content": user_message})
        answer = chat_completion_messages(messages, temperature=0.4)
        if answer:
            source = settings.copilot_llm_provider

    if not answer:
        answer, actions = _rules_product_reply(user_message, snippets)
    else:
        actions = ["Abrir Dashboard", "NOC Copilot", "Zion", "Mapa de Rede"]

    return {
        "answer": answer,
        "suggested_actions": actions,
        "source": source,
        "provider": resolve_llm_config()["provider"] if llm_available() else "rules-engine",
        "model": resolve_llm_config()["model"] if llm_available() else None,
        "llm_enabled": llm_available(),
        "knowledge_hits": snippets[:8],
        "context_snapshot": noc_ctx or {},
    }


def chatbot_status() -> dict:
    cfg = resolve_llm_config()
    return {
        "llm_enabled": llm_available(),
        "provider": cfg["provider"],
        "model": cfg["model"],
        "base_url": cfg["base_url"],
        "deepseek_docs": "https://github.com/deepseek-ai",
        "modes": {
            "chatbot": "Ajuda sobre o produto SentinelAI (features, menus, configuração)",
            "noc_copilot": "Assistente operacional (devices, alertas, anomalias)",
        },
    }

"""Cliente LLM OpenAI-compatible — OpenAI, DeepSeek API ou Ollama local.

DeepSeek (open-source / API): https://github.com/deepseek-ai
API cloud: https://api.deepseek.com (compatible com /v1/chat/completions)
Local: Ollama com modelo deepseek-r1 / deepseek-v3 em COPILOT_LLM_BASE_URL.

Docs: docs/LLM-DEEPSEEK-OLLAMA.md
"""

from __future__ import annotations

import asyncio
import logging
import time
from collections import deque
from typing import Any

import httpx

from app.config import settings

logger = logging.getLogger(__name__)

PROVIDER_PRESETS: dict[str, dict[str, str]] = {
    "deepseek": {
        "base_url": "https://api.deepseek.com",
        "model": "deepseek-chat",
    },
    "openai": {
        "base_url": "https://api.openai.com/v1",
        "model": "gpt-4o-mini",
    },
    "ollama": {
        "base_url": "http://host.docker.internal:11434/v1",
        "model": "deepseek-r1:latest",
    },
}

_RATE_LOCK = asyncio.Lock()
_RATE_HITS: deque[float] = deque()


def resolve_llm_config() -> dict[str, Any]:
    provider = (settings.copilot_llm_provider or "openai").lower().strip()
    preset = PROVIDER_PRESETS.get(provider, {})
    base_url = settings.copilot_llm_base_url.strip() or preset.get("base_url", "https://api.openai.com/v1")
    model = settings.copilot_llm_model.strip() or preset.get("model", "gpt-4o-mini")
    if provider == "deepseek" and base_url.rstrip("/").endswith("api.deepseek.com"):
        if not base_url.rstrip("/").endswith("/v1"):
            base_url = base_url.rstrip("/") + "/v1"
    return {
        "provider": provider,
        "base_url": base_url.rstrip("/"),
        "model": model,
        "api_key": settings.copilot_llm_api_key or ("ollama" if provider == "ollama" else ""),
        "max_tokens": settings.copilot_llm_max_tokens,
    }


def llm_available() -> bool:
    if not settings.copilot_llm_enabled:
        return False
    cfg = resolve_llm_config()
    if cfg["provider"] == "ollama":
        return True
    return bool(cfg["api_key"])


def _http_timeout() -> httpx.Timeout:
    return httpx.Timeout(
        connect=float(getattr(settings, "copilot_llm_connect_timeout", 5.0)),
        read=float(getattr(settings, "copilot_llm_read_timeout", 60.0)),
        write=30.0,
        pool=5.0,
    )


async def _acquire_rate_slot() -> bool:
    """Sliding window: max N requests / 60s. Retorna False se excedeu."""
    limit = int(getattr(settings, "copilot_llm_rate_limit_per_minute", 30) or 30)
    if limit <= 0:
        return True
    now = time.monotonic()
    async with _RATE_LOCK:
        while _RATE_HITS and now - _RATE_HITS[0] > 60.0:
            _RATE_HITS.popleft()
        if len(_RATE_HITS) >= limit:
            logger.warning("LLM rate limit atingido (%s/min)", limit)
            return False
        _RATE_HITS.append(now)
        return True


async def achat_completion_messages(
    messages: list[dict[str, str]],
    *,
    temperature: float = 0.3,
) -> str | None:
    if not llm_available():
        return None
    if not await _acquire_rate_slot():
        return None

    cfg = resolve_llm_config()
    url = f"{cfg['base_url']}/chat/completions"
    headers = {"Content-Type": "application/json"}
    if cfg["api_key"]:
        headers["Authorization"] = f"Bearer {cfg['api_key']}"

    payload = {
        "model": cfg["model"],
        "messages": messages,
        "max_tokens": cfg["max_tokens"],
        "temperature": temperature,
    }
    try:
        async with httpx.AsyncClient(timeout=_http_timeout()) as client:
            resp = await client.post(url, headers=headers, json=payload)
        if resp.status_code == 429:
            logger.warning("LLM rate-limited by provider (429)")
            return None
        if resp.status_code >= 500:
            logger.warning("LLM server error %s: %s", resp.status_code, resp.text[:300])
            return None
        if resp.status_code != 200:
            logger.warning("LLM API error %s: %s", resp.status_code, resp.text[:300])
            return None
        data = resp.json()
        content = data["choices"][0]["message"]["content"]
        return (content or "").strip() or None
    except Exception as exc:
        logger.warning("LLM request failed: %s", exc)
        return None


def chat_completion_messages(messages: list[dict[str, str]], *, temperature: float = 0.3) -> str | None:
    """Wrapper sync para Celery / callers legados."""
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None
    if loop and loop.is_running():
        # Evita deadlock: cria task em thread com loop próprio
        import concurrent.futures

        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            return pool.submit(
                lambda: asyncio.run(achat_completion_messages(messages, temperature=temperature))
            ).result(timeout=90)
    return asyncio.run(achat_completion_messages(messages, temperature=temperature))


def chat_completion(system_prompt: str, user_message: str) -> str | None:
    return chat_completion_messages(
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ]
    )


async def achat_completion(system_prompt: str, user_message: str) -> str | None:
    return await achat_completion_messages(
        [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_message},
        ]
    )


