import logging

from app.config import settings

logger = logging.getLogger(__name__)
_tracer = None


def setup_tracing() -> None:
    global _tracer
    if not settings.otel_enabled:
        return

    try:
        from opentelemetry import trace
        from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
        from opentelemetry.sdk.resources import Resource
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor

        resource = Resource.create(
            {
                "service.name": "sentinelai-api",
                "service.version": "1.4.0",
                "deployment.region": settings.api_region,
            }
        )
        provider = TracerProvider(resource=resource)
        exporter = OTLPSpanExporter(endpoint=f"{settings.otel_exporter_endpoint.rstrip('/')}/v1/traces")
        provider.add_span_processor(BatchSpanProcessor(exporter))
        trace.set_tracer_provider(provider)
        _tracer = trace.get_tracer("sentinelai")
        logger.info("OpenTelemetry tracing enabled → %s", settings.otel_exporter_endpoint)
    except Exception as exc:
        logger.warning("OpenTelemetry setup failed: %s", exc)


