                url,
                json={"chat_id": chat_id, "text": f"{subject}\n\n{body}", "parse_mode": "Markdown"},
            )
        return (response.status_code == 200, response.text[:400])

    if channel in {"discord", "slack", "teams", "webhook"}:
        url = destination or str(cfg.get("url") or "").strip()
        if not url:
            return False, "URL do webhook ausente"
        if channel == "discord":
