"""Credenciais de coleta: device → tag → site → settings (.env)."""

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from typing import Any, Literal

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.config import settings
from app.models import CollectCredential, Device, Site
from app.services.secret_crypto import decrypt_secret, encrypt_secret

ScopeType = Literal["device", "site", "tag"]
SECRET_KEYS = frozenset(
    {
        "community",
        "auth_key",
        "priv_key",
        "password",
    }
)


@dataclass
class SnmpAuth:
    version: str = "v2c"  # v2c | v3
    community: str | None = None
    username: str | None = None
    auth_protocol: str | None = None  # SHA | MD5
    auth_key: str | None = None
    priv_protocol: str | None = None  # AES | DES
    priv_key: str | None = None
    security_level: str = "authPriv"  # noAuthNoPriv | authNoPriv | authPriv
    source: str = "settings"


def _encrypt_payload(payload: dict[str, Any]) -> dict[str, Any]:
    out = deepcopy(payload)
    for section in ("snmp", "wmi", "ssh"):
        block = out.get(section)
        if not isinstance(block, dict):
            continue
        for key in SECRET_KEYS:
            if key in block and block[key] not in (None, ""):
                block[key] = encrypt_secret(str(block[key]))
    return out


def _decrypt_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    if not payload:
        return {}
    out = deepcopy(payload)
    for section in ("snmp", "wmi", "ssh"):
        block = out.get(section)
        if not isinstance(block, dict):
            continue
        for key in SECRET_KEYS:
            if key in block and block[key] not in (None, ""):
                plain = decrypt_secret(str(block[key]))
                if plain is not None:
                    block[key] = plain
    return out


def mask_payload(payload: dict[str, Any] | None, *, resolved_from: str | None = None) -> dict[str, Any]:
    """Resposta de API sem secrets em claro."""
    data = deepcopy(payload or {})
    result: dict[str, Any] = {"resolved_from": resolved_from}
    for section in ("snmp", "wmi", "ssh"):
        block = data.get(section)
        if not isinstance(block, dict):
            continue
        safe: dict[str, Any] = {}
        for key, value in block.items():
            if key in SECRET_KEYS:
                safe[f"{key}_set"] = bool(value)
            else:
                safe[key] = value
        result[section] = safe
    return result


def _get_row(session: Session, scope_type: ScopeType, scope_key: str) -> CollectCredential | None:
    return session.execute(
        select(CollectCredential).where(
            CollectCredential.scope_type == scope_type,
            CollectCredential.scope_key == str(scope_key),
        )
    ).scalar_one_or_none()


def get_raw_credentials(session: Session, scope_type: ScopeType, scope_key: str) -> dict[str, Any]:
    row = _get_row(session, scope_type, scope_key)
    if not row or not row.payload:
        return {}
    return _decrypt_payload(row.payload)


def upsert_credentials(
    session: Session,
    *,
    scope_type: ScopeType,
    scope_key: str,
    patch: dict[str, Any],
    updated_by: str | None = None,
) -> dict[str, Any]:
    """Mescla patch. Secrets vazios = manter; null = limpar."""
    current = get_raw_credentials(session, scope_type, scope_key)
    merged = deepcopy(current)

    for section in ("snmp", "wmi", "ssh"):
        if section not in patch:
            continue
        incoming = patch[section]
        if incoming is None:
            merged.pop(section, None)
            continue
        if not isinstance(incoming, dict):
            continue
        base = dict(merged.get(section) or {})
        for key, value in incoming.items():
            if key in SECRET_KEYS:
                if value is None:
                    base.pop(key, None)
                elif value == "" or value == "********":
                    continue  # keep existing
                else:
                    base[key] = value
            else:
                if value is None:
                    base.pop(key, None)
                else:
                    base[key] = value
        if base:
            merged[section] = base
        else:
            merged.pop(section, None)

    encrypted = _encrypt_payload(merged)
    row = _get_row(session, scope_type, scope_key)
    if row is None:
        row = CollectCredential(scope_type=scope_type, scope_key=str(scope_key), payload=encrypted)
        session.add(row)
    else:
        row.payload = encrypted
    row.updated_by = updated_by
    session.flush()
    return mask_payload(merged)


def delete_credentials(session: Session, scope_type: ScopeType, scope_key: str) -> bool:
    row = _get_row(session, scope_type, scope_key)
    if not row:
        return False
    session.delete(row)
    session.flush()
    return True


def _snmp_from_dict(data: dict[str, Any] | None, source: str) -> SnmpAuth | None:
    if not data:
        return None
    version = str(data.get("version") or "v2c").lower()
    if version in {"3", "v3", "snmpv3"}:
        username = data.get("username")
        if not username:
            return None
        return SnmpAuth(
            version="v3",
            username=str(username),
            auth_protocol=(str(data["auth_protocol"]).upper() if data.get("auth_protocol") else None),
            auth_key=data.get("auth_key"),
            priv_protocol=(str(data["priv_protocol"]).upper() if data.get("priv_protocol") else None),
            priv_key=data.get("priv_key"),
            security_level=str(data.get("security_level") or "authPriv"),
            source=source,
        )
    community = data.get("community")
    if not community:
        return None
    return SnmpAuth(version="v2c", community=str(community), source=source)


def resolve_snmp_auth(session: Session, device: Device) -> SnmpAuth:
    """Cascata: device → tag → site → settings / legacy extra_data."""
    device_creds = get_raw_credentials(session, "device", str(device.id))
    auth = _snmp_from_dict(device_creds.get("snmp"), "device")
    if auth:
        return auth

    for tag in device.tags or []:
        tag_creds = get_raw_credentials(session, "tag", str(tag))
        auth = _snmp_from_dict(tag_creds.get("snmp"), f"tag:{tag}")
        if auth:
            return auth

    if device.site_id:
        site_creds = get_raw_credentials(session, "site", str(device.site_id))
        auth = _snmp_from_dict(site_creds.get("snmp"), "site")
        if auth:
            return auth
        site = session.get(Site, device.site_id)
        if site and isinstance(site.default_credentials, dict):
            auth = _snmp_from_dict(_decrypt_payload(site.default_credentials).get("snmp"), "site")
            if auth:
                return auth

    legacy = ((device.extra_data or {}).get("snmp") or {}).get("community")


