        deleted = cleanup_old_metrics(session, retention_days=retention_days)
        session.commit()
    return {"deleted": deleted, "retention_days": retention_days}

import asyncio
import json
import logging
from dataclasses import dataclass, field

from fastapi import WebSocket

logger = logging.getLogger(__name__)


@dataclass
class MapPresence:
    username: str
    color: str
    cursor: dict = field(default_factory=lambda: {"x": 0, "y": 0})


class MapCollabManager:
    def __init__(self) -> None:
        self._rooms: dict[str, dict[WebSocket, MapPresence]] = {}
        self._lock = asyncio.Lock()
        self._colors = ["#3b82f6", "#22c55e", "#f59e0b", "#ef4444", "#8b5cf6", "#06b6d4"]

    async def connect(self, room: str, websocket: WebSocket, username: str) -> MapPresence:
        async with self._lock:
            if room not in self._rooms:
                self._rooms[room] = {}
            color = self._colors[len(self._rooms[room]) % len(self._colors)]
            presence = MapPresence(username=username, color=color)
            self._rooms[room][websocket] = presence
        await self.broadcast(room, {"type": "user_joined", "username": username, "color": color}, exclude=websocket)
        await self.broadcast_presence(room)
        return presence

    async def disconnect(self, room: str, websocket: WebSocket) -> None:
        async with self._lock:
            room_clients = self._rooms.get(room, {})
            presence = room_clients.pop(websocket, None)
            if not room_clients and room in self._rooms:
                del self._rooms[room]
        if presence:
            await self.broadcast(room, {"type": "user_left", "username": presence.username})
            await self.broadcast_presence(room)

    async def broadcast(self, room: str, message: dict, exclude: WebSocket | None = None) -> None:
        room_clients = self._rooms.get(room, {})
        dead: list[WebSocket] = []
        for ws in room_clients:
            if ws is exclude:
                continue
            try:
                await ws.send_json(message)
            except Exception:
                dead.append(ws)
        for ws in dead:
            room_clients.pop(ws, None)

    async def broadcast_presence(self, room: str) -> None:
        room_clients = self._rooms.get(room, {})
        users = [
            {"username": p.username, "color": p.color, "cursor": p.cursor}
            for p in room_clients.values()
        ]
        await self.broadcast(room, {"type": "presence", "users": users})

    async def handle_message(self, room: str, websocket: WebSocket, data: dict) -> None:
        room_clients = self._rooms.get(room, {})
        presence = room_clients.get(websocket)
        if not presence:
            return

        msg_type = data.get("type")
        if msg_type == "cursor":
            presence.cursor = {"x": data.get("x", 0), "y": data.get("y", 0)}
            await self.broadcast(
                room,
                {"type": "cursor", "username": presence.username, "color": presence.color, "x": data.get("x"), "y": data.get("y")},
                exclude=websocket,
            )
        elif msg_type == "node_move":
            await self.broadcast(
                room,
                {
                    "type": "node_move",
                    "username": presence.username,
                    "node_id": data.get("node_id"),
                    "x": data.get("x"),
                    "y": data.get("y"),
                },
                exclude=websocket,
            )
        elif msg_type == "layout_saved":
            await self.broadcast(room, {"type": "layout_saved", "username": presence.username})


