import { useCallback, useEffect, useRef, useState } from "react";
import { MessageCircle, Send, X } from "lucide-react";
import { chatbotChat } from "../api/client";

interface ChatMessage {
  role: "user" | "assistant";
  text: string;
}

export default function ChatbotWidget() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: "assistant", text: "Chatbot SentinelAI — pergunte sobre módulos, menus ou DeepSeek." },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (open) bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, open]);

  const send = useCallback(async () => {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    setMessages((m) => [...m, { role: "user", text }]);
    setLoading(true);
    try {
      const history = messages.slice(-6).map((m) => ({ role: m.role, content: m.text }));
      const res = await chatbotChat(text, history);
      setMessages((m) => [...m, { role: "assistant", text: res.answer }]);
    } catch (e) {
      setMessages((m) => [...m, { role: "assistant", text: String(e) }]);
    } finally {
      setLoading(false);
    }
  }, [input, loading, messages]);

  return (
    <div className="sa-chatbot-widget">
      {open && (
        <div className="sa-chatbot-panel" role="dialog" aria-label="Chatbot SentinelAI">
          <div className="sa-chatbot-panel-header">
            <span>
              <MessageCircle size={16} style={{ verticalAlign: "middle", marginRight: 6 }} />
              Chatbot
            </span>
            <button type="button" className="sa-btn sa-btn-ghost sa-btn-icon" onClick={() => setOpen(false)} aria-label="Fechar">
              <X size={16} />
            </button>
          </div>
          <div className="sa-chatbot-panel-body">
            {messages.map((msg, i) => (
              <div key={i} className={`sa-chatbot-bubble sa-chatbot-bubble-${msg.role}`}>
                {msg.text}
              </div>
            ))}
            {loading && <div className="sa-text-muted" style={{ fontSize: 12 }}>…</div>}
            <div ref={bottomRef} />
          </div>
          <div className="sa-chatbot-panel-footer">
            <input
              className="sa-input"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && send()}
              placeholder="Pergunte sobre o SentinelAI…"
              disabled={loading}
            />
            <button type="button" className="sa-btn sa-btn-primary sa-btn-icon" onClick={send} disabled={loading}>
              <Send size={16} />
            </button>
          </div>
        </div>
      )}
      <button
        type="button"
        className="sa-chatbot-fab"
        onClick={() => setOpen((v) => !v)}
        title="Chatbot SentinelAI"
        aria-label="Abrir chatbot"
      >
        {open ? <X size={22} /> : <MessageCircle size={22} />}
      </button>
    </div>
  );
}

