import { useCallback, useEffect, useState } from "react";
import { Download, GitCompare, RefreshCw, ShieldCheck } from "lucide-react";
import {
  fetchConfigBackups,
  fetchConfigBackupDetail,
  fetchConfigDiff,
  requestConfigRestore,
  triggerConfigBackup,
  type ConfigBackup,
  type ConfigDiff,
} from "../api/client";

export default function DeviceConfigTab({ deviceId }: { deviceId: number }) {
  const [backups, setBackups] = useState<ConfigBackup[]>([]);
  const [selected, setSelected] = useState<string>("");
  const [compareWith, setCompareWith] = useState<string>("");
  const [preview, setPreview] = useState<string>("");
  const [diff, setDiff] = useState<ConfigDiff | null>(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  const load = useCallback(async () => {
    const list = await fetchConfigBackups(deviceId);
    setBackups(list);
    if (list.length && !selected) {
      setSelected(String(list[0].id));
      if (list.length > 1) setCompareWith(String(list[1].id));
    }
  }, [deviceId, selected]);

  useEffect(() => {
    load().catch(() => undefined);
  }, [load]);

  useEffect(() => {
    if (!selected) {
      setPreview("");
      return;
    }
    fetchConfigBackupDetail(deviceId, Number(selected))
      .then((d) => setPreview(d.content || ""))
      .catch(() => setPreview(""));
  }, [deviceId, selected]);

  async function handleBackup() {
    setLoading(true);
    try {
      await triggerConfigBackup(deviceId);
      setMessage("Backup iniciado. Atualize em alguns segundos.");
      setTimeout(() => load().catch(() => undefined), 3000);
    } catch (e) {
      setMessage(String(e));
    } finally {
      setLoading(false);
    }
  }

  async function handleDownload() {
    if (!selected) return;
    const detail = await fetchConfigBackupDetail(deviceId, Number(selected));
    const blob = new Blob([detail.content], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `config-${deviceId}-${selected}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }

  async function handleDiff() {
    if (!selected || !compareWith) return;
    try {
      const d = await fetchConfigDiff(deviceId, Number(compareWith), Number(selected));
      setDiff(d);
      setMessage(d.changed ? "Diff gerado — há diferenças." : "Diff gerado — configs idênticas.");
    } catch (e) {
      setMessage(String(e));
    }
  }

  async function handleRestoreRequest() {
    if (!selected) return;
    try {
      const r = await requestConfigRestore(deviceId, Number(selected));
      setMessage(`${r.message} (aprovação #${r.approval_id})`);
    } catch (e) {
      setMessage(String(e));
    }
  }

  const current = backups.find((b) => String(b.id) === selected);

  return (
    <div className="sa-stack">
      <div className="sa-map-actions">
        <button type="button" className="sa-btn sa-btn-primary" onClick={handleBackup} disabled={loading}>
          {loading ? <span className="sa-spinner" /> : <RefreshCw size={16} />}
          Backup SSH agora
        </button>
        {current && (
          <>
            <button type="button" className="sa-btn sa-btn-secondary" onClick={handleDownload}>
              <Download size={16} /> Baixar
            </button>
            <button type="button" className="sa-btn sa-btn-secondary" onClick={handleDiff} disabled={!compareWith}>
              <GitCompare size={16} /> Diff
            </button>
            <button type="button" className="sa-btn sa-btn-secondary" onClick={handleRestoreRequest}>
              <ShieldCheck size={16} /> Pedir restore
            </button>
          </>
        )}
      </div>
      {message && <p className="sa-text-muted">{message}</p>}
      {backups.length === 0 ? (
        <p className="sa-empty">
          Nenhum backup. Configure SSH_DEFAULT_USERNAME/PASSWORD no .env ou credenciais em extra_data.ssh do device.
        </p>
      ) : (
        <>
          <div className="sa-map-actions" style={{ flexWrap: "wrap" }}>
            <label className="sa-text-muted" style={{ fontSize: 12 }}>
              Atual
              <select className="sa-input" value={selected} onChange={(e) => setSelected(e.target.value)}>
                {backups.map((b) => (
                  <option key={b.id} value={b.id}>
                    {new Date(b.created_at).toLocaleString("pt-BR")} · {b.content_hash.slice(0, 12)}…
                    {b.changed ? " · mudou" : ""}
                  </option>
                ))}
              </select>
            </label>
            <label className="sa-text-muted" style={{ fontSize: 12 }}>
              Comparar com
              <select className="sa-input" value={compareWith} onChange={(e) => setCompareWith(e.target.value)}>
                <option value="">—</option>
                {backups.map((b) => (
                  <option key={b.id} value={b.id}>
                    {new Date(b.created_at).toLocaleString("pt-BR")} · {b.content_hash.slice(0, 12)}…
                  </option>
                ))}
              </select>
            </label>
          </div>
          {diff && (
            <pre className="sa-config-preview" style={{ maxHeight: 240, overflow: "auto", fontSize: 11 }}>
              {diff.unified_diff || "(sem diferenças)"}
            </pre>
          )}
          <pre className="sa-config-preview" style={{ maxHeight: 320, overflow: "auto", fontSize: 11 }}>
            {preview || "Carregando…"}
          </pre>
        </>
      )}
    </div>
  );
}

