        if (preferredMetric && names.includes(preferredMetric)) {
          setSelected(preferredMetric);
        } else if (!names.includes(selected) && names.length) {
          const latency = names.find((n) => LATENCY_METRICS.has(n));
          const custom = names.find((n) => n.startsWith("custom_oid:"));
          setSelected(latency || custom || names[0]);
        }
      })
      .catch(() => undefined)
      .finally(() => setLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [deviceId, preferredMetric]);

  const metricNames = useMemo(() => [...new Set(metrics.map((m) => m.metric_name))].sort(), [metrics]);

  const series = useMemo(
    () => metrics.filter((m) => m.metric_name === selected),
    [metrics, selected],
  );

  const chartData = series.map((m) => ({
    time: new Date(m.recorded_at).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }),
    value: m.value,
    name: m.metric_name,
  }));

  const unit = series[0]?.unit || (LATENCY_METRICS.has(selected) ? "ms" : "");

  if (loading) {
    return <p className="sa-text-muted">Carregando métricas...</p>;
  }

  return (
    <div className="sa-stack" style={{ gap: "var(--sa-space-md)" }}>
      {sla && (
        <div className="sa-stat-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
          <StatCard
            label={`Uptime (${sla.days}d)`}
            value={sla.uptime_percent != null ? `${sla.uptime_percent}%` : "—"}
            icon={Percent}
            variant="green"
          />
          <StatCard
            label="Latência média"
            value={sla.avg_latency_ms != null ? `${sla.avg_latency_ms} ms` : "—"}
            icon={Clock}
          />
          <StatCard label="Amostras" value={sla.samples} icon={Activity} variant="blue" />
        </div>
      )}

      {metricNames.length > 0 && (
        <label className="sa-field" style={{ maxWidth: 320 }}>
          <span className="sa-label">Série (24h)</span>
          <select className="sa-input" value={selected} onChange={(e) => setSelected(e.target.value)}>
            {metricNames.map((name) => (
              <option key={name} value={name}>
                {name.startsWith("custom_oid:") ? `OID ${name}` : name}
              </option>
            ))}
          </select>
        </label>
      )}

      {chartData.length === 0 ? (
        <p className="sa-empty">Sem métricas nas últimas 24h. Aguarde o worker ou execute Poll no sensor OID.</p>
      ) : (
        <div style={{ height: 260 }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData}>
              <XAxis dataKey="time" tick={{ fontSize: 11 }} stroke="var(--sa-text-muted)" />
              <YAxis tick={{ fontSize: 11 }} stroke="var(--sa-text-muted)" unit={unit ? ` ${unit}` : undefined} />
              <Tooltip
                contentStyle={{
                  background: "var(--sa-surface)",
                  border: "1px solid var(--sa-border)",
                  borderRadius: "8px",
                }}
              />
              <Line type="monotone" dataKey="value" stroke="var(--sa-primary)" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useState } from "react";
import {
  createMonitor,
  deleteMonitor,
  fetchMonitors,
  updateMonitor,
  type Monitor,
} from "../api/client";
import { useAuth } from "../context/AuthContext";
import StatusBadge from "./ui/StatusBadge";

const MONITOR_TYPES = ["ping", "http", "https", "tcp"] as const;

export default function DeviceMonitorsTab({ deviceId }: { deviceId: number }) {
  const { canWrite } = useAuth();
  const [monitors, setMonitors] = useState<Monitor[]>([]);
  const [form, setForm] = useState({ monitor_type: "http" as Monitor["monitor_type"], target: "", interval_seconds: 60 });

  const load = useCallback(() => {
    fetchMonitors(deviceId).then(setMonitors).catch(() => undefined);
  }, [deviceId]);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <div className="sa-stack" style={{ gap: "var(--sa-space-md)" }}>
      {canWrite && (
        <form
          className="sa-form-row"
          onSubmit={(e) => {
            e.preventDefault();
            createMonitor({
              device_id: deviceId,
              monitor_type: form.monitor_type,
              target: form.target || null,
              interval_seconds: form.interval_seconds,
            })
              .then(() => {
                setForm({ monitor_type: "http", target: "", interval_seconds: 60 });
                load();
              })
              .catch(() => undefined);
          }}
        >
          <select
            className="sa-input"
            value={form.monitor_type}
            onChange={(e) => setForm({ ...form, monitor_type: e.target.value as Monitor["monitor_type"] })}
          >
            {MONITOR_TYPES.map((t) => (
              <option key={t} value={t}>{t.toUpperCase()}</option>
            ))}
          </select>
          <input
            className="sa-input"
            placeholder="Target (URL ou host:porta)"
            value={form.target}
            onChange={(e) => setForm({ ...form, target: e.target.value })}
          />
          <input
            className="sa-input"
            type="number"
            min={15}
            max={3600}
            value={form.interval_seconds}
            onChange={(e) => setForm({ ...form, interval_seconds: Number(e.target.value) })}
            style={{ width: 100 }}
          />
          <button type="submit" className="sa-btn sa-btn-primary">Adicionar</button>
        </form>
      )}
      {monitors.length === 0 ? (
        <p className="sa-empty">Nenhum monitor configurado (ping é criado automaticamente).</p>
      ) : (
        <div className="sa-table-wrap">
          <table className="sa-table">
            <thead>
              <tr>
                <th>Tipo</th>
                <th>Target</th>
                <th>Intervalo</th>
                <th>Status</th>
                {canWrite && <th />}
              </tr>
            </thead>
            <tbody>
              {monitors.map((m) => (
                <tr key={m.id}>
                  <td>{m.monitor_type.toUpperCase()}</td>
                  <td>{m.target ?? "(padrão IP)"}</td>
                  <td>{m.interval_seconds}s</td>
                  <td><StatusBadge status={m.is_enabled ? "active" : "inactive"} /></td>
                  {canWrite && (
                    <td style={{ display: "flex", gap: 4 }}>
                      <button
                        type="button"
                        className="sa-btn sa-btn-ghost sa-btn-sm"
                        onClick={() => updateMonitor(m.id, { is_enabled: !m.is_enabled }).then(load)}
                      >
                        {m.is_enabled ? "Desativar" : "Ativar"}
                      </button>
                      {m.monitor_type !== "ping" && (
                        <button
                          type="button"
                          className="sa-btn sa-btn-ghost sa-btn-sm"
                          onClick={() => deleteMonitor(m.id).then(load)}
                        >
                          Remover
                        </button>
                      )}
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { type NodeProps } from "@xyflow/react";
import { Trash2 } from "lucide-react";
import { useEffect, useRef, type CSSProperties } from "react";
import { getDeviceEmoji, getDeviceTypeColor, getDeviceTypeLabel } from "../constants/deviceTypes";
import { useMapActions } from "../context/MapActionsContext";
import MapNodeHandles from "./map/MapNodeHandles";

export default function DeviceNode({ data, selected }: NodeProps) {
  const { canWrite, onDeleteDevice } = useMapActions();
  const status = data.status as string;
  const deviceType = (data.device_type as string) || "unknown";
  const deviceId = data.device_id as number | undefined;
  const ip = String(data.ip_address ?? "—");
  const name = String(data.label ?? "");
  const deviceLabel = name && name !== ip ? name : getDeviceTypeLabel(deviceType);
  const typeColor = getDeviceTypeColor(deviceType);
  const isOnline = status === "active";
  // Amarelo só se já ficou online no mapa (flag explícita) — não usar last_seen histórico
  const wasEverOnline = Boolean(data.was_ever_online) || isOnline;
  const showDownAlert = !isOnline && wasEverOnline;
  const statusClass = isOnline
    ? "sa-topo-node-online"
    : showDownAlert
      ? "sa-topo-node-down-alert"
      : "sa-topo-node-offline";

  const ref = useRef<HTMLDivElement>(null);
  const prevStatus = useRef(status);

  useEffect(() => {
    if (prevStatus.current !== status && ref.current) {
      ref.current.classList.add("sa-topo-node-pulse");
      const timer = setTimeout(() => ref.current?.classList.remove("sa-topo-node-pulse"), 800);
      prevStatus.current = status;
      return () => clearTimeout(timer);
    }
    prevStatus.current = status;
  }, [status]);

  return (
    <div
      className="sa-map-node-frame"
      style={{ "--sa-topo-type-color": typeColor } as CSSProperties}
    >
      <MapNodeHandles connectable={canWrite} />
      {showDownAlert && <span className="sa-topo-node-alert-ring" aria-hidden="true" />}
      {canWrite && deviceId != null && (
        <button
          type="button"
          className="sa-topo-node-delete"
          title={`Remover ${deviceLabel}`}
          onClick={(e) => {
            e.stopPropagation();
            onDeleteDevice(deviceId, deviceLabel, ip);
          }}
        >
          <Trash2 size={12} />
        </button>
      )}
      <div
        ref={ref}
        className={`sa-topo-node ${statusClass}${selected ? " sa-topo-node-selected" : ""}`}
        style={
          {
            border: showDownAlert ? undefined : `3px solid ${typeColor}`,
            background: "var(--sa-surface)",
          } as CSSProperties
        }
      >
        <div className="sa-topo-node-icon">{getDeviceEmoji(deviceType)}</div>
        <strong>{data.label as string}</strong>
        <small>{data.ip_address as string}</small>
        <span className="sa-topo-status-pill">
          {isOnline ? "Online" : showDownAlert ? "Offline — alerta" : status === "unknown" ? "Aguardando ping…" : "Offline"}
        </span>
      </div>
    </div>
  );
}

import { Cell, Pie, PieChart, ResponsiveContainer, Tooltip } from "recharts";
import type { CSSProperties } from "react";
import type { Device } from "../api/client";

interface DeviceStatusChartProps {
  devices: Device[];
}

const STATUS_COLORS = {
  Online: "var(--sa-success)",
  Offline: "var(--sa-danger)",
  Outros: "var(--sa-warning)",
} as const;

function availabilityGlow(percent: number): string {
  if (percent >= 80) return "var(--sa-success)";
  if (percent >= 50) return "var(--sa-warning)";
  return "var(--sa-danger)";
}

export default function DeviceStatusChart({ devices }: DeviceStatusChartProps) {
  const online = devices.filter((d) => d.status === "active").length;
  const offline = devices.filter((d) => d.status === "inactive").length;
  const other = devices.length - online - offline;

  const slices = [
    { name: "Online" as const, value: online, color: STATUS_COLORS.Online },
    { name: "Offline" as const, value: offline, color: STATUS_COLORS.Offline },
    { name: "Outros" as const, value: other, color: STATUS_COLORS.Outros },
  ].filter((d) => d.value > 0);

  if (slices.length === 0) {
    return <p className="sa-empty">Nenhum dispositivo no mapa ainda.</p>;
  }

  const availability = devices.length ? Math.round((online / devices.length) * 100) : 0;
  const glowColor = availabilityGlow(availability);

  return (
    <div className="sa-status-chart">
      <div
        className="sa-status-chart-visual"
        style={{ "--status-glow": glowColor } as CSSProperties}
      >
        <div className="sa-status-chart-glow" aria-hidden />
        <div className="sa-status-chart-ring" aria-hidden />
        <div className="sa-status-chart-donut">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={slices}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={54}
                outerRadius={76}
                paddingAngle={4}
                stroke="none"
                isAnimationActive
                animationDuration={900}
                animationEasing="ease-out"
              >
                {slices.map((entry) => (
                  <Cell key={entry.name} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip
                formatter={(value: number, name: string) => [`${value} dispositivo(s)`, name]}
                contentStyle={{
                  background: "var(--sa-bg-elevated)",
                  border: "1px solid var(--sa-border)",
                  borderRadius: "var(--sa-radius-sm)",
                  fontSize: 13,
                }}
              />
            </PieChart>
          </ResponsiveContainer>
          <div className="sa-status-chart-center">
            <span className="sa-status-chart-center-value" key={availability}>
              {availability}%
            </span>
            <span className="sa-status-chart-center-label">online</span>
          </div>
        </div>
      </div>

      <ul className="sa-status-chart-legend">
        {slices.map((slice) => (
          <li key={slice.name} className="sa-status-chart-legend-item">
            <span className="sa-status-chart-dot" style={{ backgroundColor: slice.color }} />
            <span className="sa-status-chart-legend-label">{slice.name}</span>
            <span className="sa-status-chart-legend-value">{slice.value}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useMemo } from "react";
import type { LucideIcon } from "lucide-react";
import { Shield } from "lucide-react";
import type { Device } from "../api/client";
import { getDeviceTypeColor, getDeviceTypeDef, getDeviceTypeLabel } from "../constants/deviceTypes";

interface DeviceTypeBreakdownProps {
  devices: Device[];
}

interface TypeRow {
  type: string;
  label: string;
  count: number;
  percent: number;
  color: string;
  Icon: LucideIcon;
}

export default function DeviceTypeBreakdown({ devices }: DeviceTypeBreakdownProps) {
  const rows = useMemo(() => {
    const counts: Record<string, number> = {};
    devices.forEach((d) => {
      const t = d.device_type ?? "unknown";
      counts[t] = (counts[t] ?? 0) + 1;
    });

    const total = devices.length;
    return Object.entries(counts)
      .map(([type, count]): TypeRow => {
        const def = getDeviceTypeDef(type);
        return {
          type,
          label: getDeviceTypeLabel(type),
          count,
          percent: total ? Math.round((count / total) * 100) : 0,
          color: getDeviceTypeColor(type),
          Icon: def?.icon ?? Shield,
        };
      })
      .sort((a, b) => b.count - a.count);
  }, [devices]);

  if (rows.length === 0) {
    return <p className="sa-empty">Nenhum dispositivo no mapa ainda.</p>;
  }

  const maxCount = rows[0]?.count ?? 1;

  return (
    <div className="sa-type-breakdown">
      {rows.map((row) => (
        <div key={row.type} className="sa-type-breakdown-row">
          <div className="sa-type-breakdown-head">
            <div className="sa-type-breakdown-label">
              <span
                className="sa-type-breakdown-icon"
                style={{ backgroundColor: `${row.color}22`, color: row.color }}
              >
                <row.Icon size={16} strokeWidth={2.25} />
              </span>
              <span className="sa-type-breakdown-name">{row.label}</span>
            </div>
            <div className="sa-type-breakdown-stats">
              <span className="sa-type-breakdown-count">{row.count}</span>
              <span className="sa-type-breakdown-percent">{row.percent}%</span>
            </div>
          </div>
          <div className="sa-type-breakdown-track">
            <div
              className="sa-type-breakdown-fill"
              style={{
                width: `${Math.max(8, (row.count / maxCount) * 100)}%`,
                backgroundColor: row.color,
              }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

import { Square } from "lucide-react";
import type { DiscoveryJob } from "../api/client";

export interface DiscoveryJobCounts {
  total: number;
  active: number;
  inactive: number;
}

function parseProgressTotal(job: DiscoveryJob): number {
  const match = job.progress_label?.match(/(\d+)\/(\d+)/);
  if (match) return Number(match[2]);
  return job.devices_found || job.total_hosts || 0;
}

/** Totais do scan: total na sub-rede, ativos (respondendo) e inativos. */
export function discoveryJobCounts(job: DiscoveryJob): DiscoveryJobCounts {
  const total = job.total_hosts || parseProgressTotal(job) || job.hosts_processed || 0;
  const active = job.devices_found ?? 0;
  let inactive = job.devices_inactive ?? 0;
  if (inactive === 0 && job.status === "completed" && total > active) {
    inactive = total - active;
  }
  return { total, active, inactive };
}

/** Backend é a fonte de verdade para a barra de progresso. */
function jobProgressPercent(job: DiscoveryJob): number {
  if (job.status === "completed") return 100;
  return job.progress_percent ?? 0;
}

export default function DiscoveryJobProgress({ job }: { job: DiscoveryJob }) {
  const percent = jobProgressPercent(job);
  const isActive = job.status === "pending" || job.status === "running";

  return (
    <div className={`sa-job-progress ${isActive ? "sa-job-progress-active" : ""}`}>
      <div className="sa-job-progress-head">
        <span className="sa-job-progress-value">{percent}%</span>
        {isActive && <span className="sa-job-progress-pulse" aria-hidden />}
      </div>
      <div className="sa-job-progress-track">
        <div className="sa-job-progress-fill" style={{ width: `${percent}%` }} />
      </div>
      {job.progress_label && <div className="sa-job-progress-label">{job.progress_label}</div>}
    </div>
  );
}

interface DiscoveryJobActiveBannerProps {
  job: DiscoveryJob;
  onStop?: () => void;
  stopping?: boolean;
  canStop?: boolean;
}

export function DiscoveryJobActiveBanner({
  job,
  onStop,
  stopping = false,
  canStop = false,
}: DiscoveryJobActiveBannerProps) {
  const percent = jobProgressPercent(job);
  const { total, active, inactive } = discoveryJobCounts(job);
  const profileLabel =
    job.scan_options?.profile &&
    ({
      quick: "Rápido",
      standard: "Padrão",
      deep: "Profundo",
      aggressive: "Agressivo",
      custom: "Personalizado",
    }[job.scan_options.profile] ?? job.scan_options.profile);
  const phase =
    job.status === "pending"
      ? "Na fila"
      : job.status === "completed"
        ? "Scan concluído"
        : job.status === "failed"
          ? "Scan falhou"
          : profileLabel
            ? `Scan nmap (${profileLabel})`
            : job.use_snmp
              ? "Scan nmap/SNMP em andamento"
              : "Scan em andamento";

  return (
    <div className="sa-job-active-banner">
      <div className="sa-job-active-banner-head">
        <div>
          <strong>{phase}</strong>
          <span>
            Job #{job.id} · {job.subnet}
            {total > 0 ? ` · ${total} total · ${active} ativos · ${inactive} inativos` : ""}
          </span>
        </div>
        <div className="sa-job-active-banner-actions">
          <span className="sa-job-active-banner-pct">{percent}%</span>
          {canStop && onStop && (
            <button
              type="button"
              className="sa-btn sa-btn-danger sa-btn-sm"
              disabled={stopping}
              onClick={onStop}
            >
              <Square size={14} fill="currentColor" />
              {stopping ? "Parando..." : "Stop"}
            </button>
          )}
        </div>
      </div>
      <div className="sa-job-progress-track sa-job-progress-track-lg">
        <div className="sa-job-progress-fill" style={{ width: `${percent}%` }} />
      </div>
      {job.progress_label && <p className="sa-job-active-banner-label">{job.progress_label}</p>}
    </div>
  );
}

import { ChevronDown, ChevronUp, Settings2 } from "lucide-react";
import { useState } from "react";
import type { ScanDefaultsResponse, ScanOptionsPayload, ScanProfileId } from "../api/client";

interface DiscoveryScanOptionsProps {
  value: ScanOptionsPayload;
  onChange: (value: ScanOptionsPayload) => void;
  defaults: ScanDefaultsResponse | null;
  disabled?: boolean;
}

const PROFILE_ORDER: ScanProfileId[] = ["quick", "standard", "deep", "aggressive", "custom"];

function Toggle({
  label,
  hint,
  checked,
  onChange,
  disabled,
}: {
  label: string;
  hint?: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <label className="sa-scan-opt-toggle">
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
      <span>
        {label}
        {hint ? <small>{hint}</small> : null}
      </span>
    </label>
  );
}

function NumField({
  label,
  value,
  min,
  max,
  onChange,
  disabled,
}: {
  label: string;
  value: number | undefined;
  min: number;
  max: number;
  onChange: (v: number) => void;
  disabled?: boolean;
}) {
  return (
    <label className="sa-scan-opt-field">
      <span>{label}</span>
      <input
        className="sa-input"
        type="number"
        min={min}
        max={max}
        value={value ?? ""}
        disabled={disabled}
        onChange={(e) => onChange(Number(e.target.value))}
      />
    </label>
  );
}

export default function DiscoveryScanOptions({
  value,
  onChange,
  defaults,
  disabled = false,
}: DiscoveryScanOptionsProps) {
  const [advancedOpen, setAdvancedOpen] = useState(value.profile === "custom");

  const profiles = defaults?.profiles ?? [];
  const limits = defaults?.limits;
  const isCustom = value.profile === "custom";

  function patch(partial: Partial<ScanOptionsPayload>) {
    onChange({ ...value, ...partial });
  }

  function selectProfile(profile: ScanProfileId) {
    const meta = profiles.find((p) => p.id === profile);
    if (profile === "custom") {
      onChange({ ...value, profile: "custom" });
      setAdvancedOpen(true);
      return;
    }
    onChange({
      profile,
      scan_type: "syn",
      use_snmp: profile !== "quick",
      ...(meta?.defaults as Partial<ScanOptionsPayload>),
    });
    setAdvancedOpen(false);
  }

  return (
    <div className="sa-scan-options">
      <div className="sa-scan-options-head">
        <Settings2 size={16} />
        <strong>Perfil de scan nmap</strong>
      </div>

      <div className="sa-scan-profile-grid">
        {PROFILE_ORDER.map((id) => {
          const meta = profiles.find((p) => p.id === id) ?? {
            id,
            label: id === "custom" ? "Personalizado" : id,
            description: "Configure manualmente",
          };
          const active = value.profile === id;
          return (
            <button
              key={id}
              type="button"
              className={`sa-scan-profile-card ${active ? "sa-scan-profile-card-active" : ""}`}
              disabled={disabled}
              onClick={() => selectProfile(id)}
            >
              <span className="sa-scan-profile-title">{meta.label}</span>
              <span className="sa-scan-profile-desc">{meta.description}</span>
            </button>
          );
        })}
      </div>

      <button
        type="button"
        className="sa-scan-advanced-toggle"
        disabled={disabled}
        onClick={() => setAdvancedOpen((o) => !o)}
      >
        {advancedOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        Opções avançadas {isCustom ? "(obrigatório no perfil personalizado)" : ""}
      </button>

      {advancedOpen && (
        <div className="sa-scan-advanced-panel">
          <section>
            <h4>Nmap — descoberta e portas</h4>
            <div className="sa-scan-opt-grid">
              <Toggle
                label="Apenas descoberta (-sn)"
                hint="Sem scan de portas"
                checked={Boolean(value.discover_only)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ discover_only: v, port_scan: !v })}
              />
              <Toggle
                label="Scan de portas"
                checked={value.discover_only ? false : value.port_scan !== false}
                disabled={disabled || !isCustom || Boolean(value.discover_only)}
                onChange={(v) => patch({ port_scan: v, discover_only: !v })}
              />
              <Toggle
