import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("SentinelAI UI error:", error, info);
  }

  render() {
    if (this.state.error) {
      return (
        <div className="sa-card" style={{ margin: "2rem", padding: "2rem" }}>
          <h2 style={{ margin: "0 0 0.5rem" }}>Erro na interface</h2>
          <p style={{ color: "var(--sa-text-muted)", marginBottom: "1rem" }}>
            {this.state.error.message}
          </p>
          <button type="button" className="sa-btn sa-btn-primary" onClick={() => this.setState({ error: null })}>
            Tentar novamente
          </button>
          {" "}
          <button type="button" className="sa-btn sa-btn-secondary" onClick={() => window.location.reload()}>
            Recarregar página
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

