  const offlineish = sorted.filter((d) => d.status === "offline" || d.status === "empty").length;

  return (
    <div className="sa-dept-list-panel sa-dept-list-eng">
      <div className="sa-dept-list-head">
        <div>
          <h4>
            <Building2 size={14} /> Departamentos
          </h4>
          <p className="sa-dept-list-panel-sub">
            {loading
              ? "Carregando…"
              : `${sorted.length} · ${withDevices} com assets · ${offlineish} atenção`}
          </p>
        </div>
      </div>

      {loading ? (
        <div className="sa-dept-list-empty">
          <span className="sa-spinner" />
        </div>
      ) : sorted.length === 0 ? (
        <div className="sa-dept-list-empty">
          <Building2 size={22} strokeWidth={1.5} />
          <span>Nenhum departamento no mapa</span>
        </div>
      ) : (
        <ul className="sa-dept-list">
          {sorted.map((dept) => {
            const tone = statusTone(dept.status);
            const pct =
              dept.deviceCount > 0 ? Math.round((dept.onlineCount / dept.deviceCount) * 100) : 0;
            const detail =
              dept.deviceCount === 0
                ? STATUS_LABELS.empty
                : `${dept.onlineCount}/${dept.deviceCount} online · ${STATUS_LABELS[dept.status] ?? dept.status}`;
            return (
              <li key={dept.groupId}>
                <button
                  type="button"
                  className={`sa-dept-list-item sa-dept-list-item-${tone}`}
                  onClick={() => onOpenDepartment(dept.groupId, dept.name)}
                  title={`Abrir submapa — ${dept.name} (${detail})`}
                >
                  <i className={`sa-dept-status-dot sa-dept-status-dot-${tone}`} aria-hidden="true" />
                  <span className="sa-dept-list-item-body">
                    <strong>{dept.name}</strong>
                    <small>{detail}</small>
                    {dept.deviceCount > 0 && (
                      <span className="sa-dept-gauge" aria-hidden>
                        <span className="sa-dept-gauge-fill" style={{ width: `${pct}%` }} />
                      </span>
                    )}
                  </span>
                  <ChevronRight size={14} className="sa-dept-list-item-arrow" aria-hidden="true" />
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

