export function MapAddDeviceDialog({
  open,
  canvasRef,
  deviceLabel,
  ip,
  saving = false,
  error,
  onIpChange,
  onConfirm,
  onCancel,
}: MapAddDeviceDialogProps) {
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    const t = window.setTimeout(() => {
      inputRef.current?.focus();
      inputRef.current?.select();
    }, 50);
    return () => window.clearTimeout(t);
  }, [open, deviceLabel]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onCancel();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onCancel]);

  return (
    <MapModalOverlay open={open} canvasRef={canvasRef} onBackdropClick={onCancel}>
      <div
        className="sa-map-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${inputId}-title`}
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className="sa-map-modal-header">
          <div className="sa-map-modal-icon sa-map-modal-icon-primary">
            <Network size={20} />
          </div>
          <div className="sa-map-modal-header-text">
            <h3 id={`${inputId}-title`}>
              Deseja adicionar o dispositivo &ldquo;{deviceLabel}&rdquo; ao mapa?
            </h3>
          </div>
          <button type="button" className="sa-map-modal-close" onClick={onCancel} aria-label="Fechar">
            <X size={18} />
          </button>
        </div>
        <div className="sa-map-modal-body">
          <label className="sa-label" htmlFor={inputId}>
            IP do {deviceLabel}
            <input
              ref={inputRef}
              id={inputId}
              className="sa-input"
              type="text"
              inputMode="decimal"
              autoComplete="off"
              placeholder="192.168.1.10"
              value={ip}
              disabled={saving}
              onChange={(e) => onIpChange(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && ip.trim()) onConfirm();
              }}
            />
          </label>
          {error && <p className="sa-map-modal-error">{error}</p>}
        </div>
        <div className="sa-map-modal-footer">
          <button type="button" className="sa-btn sa-btn-secondary" onClick={onCancel} disabled={saving}>
            Cancelar
          </button>
          <button
            type="button"
            className="sa-btn sa-btn-primary"
            onClick={onConfirm}
            disabled={saving || !ip.trim()}
          >
            {saving ? <span className="sa-spinner" /> : null}
            Adicionar ao mapa
          </button>
        </div>
      </div>
    </MapModalOverlay>
  );
}

