import { BaseEdge, getBezierPath, getSmoothStepPath, getStraightPath, type EdgeProps } from "@xyflow/react";

function formatBps(bps: number): string {
  if (bps >= 1_000_000_000) return `${(bps / 1_000_000_000).toFixed(1)} Gbps`;
  if (bps >= 1_000_000) return `${(bps / 1_000_000).toFixed(1)} Mbps`;
  if (bps >= 1_000) return `${(bps / 1_000).toFixed(0)} Kbps`;
  return `${Math.round(bps)} bps`;
}

function getPath(edgeStyle: string, params: Parameters<typeof getSmoothStepPath>[0]): [string, number, number] {
  if (edgeStyle === "straight") {
    const [path, lx, ly] = getStraightPath(params);
    return [path, lx, ly];
  }
  if (edgeStyle === "default") {
    const [path, lx, ly] = getBezierPath(params);
    return [path, lx, ly];
  }
  const [path, lx, ly] = getSmoothStepPath(params);
  return [path, lx, ly];
}

export default function TrafficEdge(props: EdgeProps) {
  const {
    id,
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
    data,
    markerEnd,
    selected,
  } = props;

  const edgeStyle = (data?.edgeStyle as string) || "smoothstep";
  const bpsOut = (data?.bps_out as number) ?? 0;
  const bpsIn = (data?.bps_in as number) ?? 0;
  const isActive = data?.status !== "inactive";
  const maxBps = Math.max(bpsIn, bpsOut);
  const strokeWidth = selected ? 6 : 5;
  const strokeColor = selected ? "#60a5fa" : isActive ? "#22c55e" : "#64748b";
  const duration = maxBps > 0 ? Math.max(1.2, 5 - Math.log10(maxBps + 1)) : 2.4;
  const trafficLabel = maxBps > 0 ? formatBps(maxBps) : null;

  const [edgePath, labelX, labelY] = getPath(edgeStyle, {
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  });

  return (
    <>
      <BaseEdge
        id={id}
        path={edgePath}
        markerEnd={markerEnd}
        interactionWidth={selected ? 20 : 6}
        style={{
          strokeWidth,
          stroke: strokeColor,
          opacity: isActive ? 1 : 0.45,
          filter: selected ? "drop-shadow(0 0 4px rgba(96,165,250,0.6))" : undefined,
        }}
      />
      {trafficLabel && (
        <>
          <rect
            x={labelX - 36}
            y={labelY - 10}
            width={72}
            height={20}
            rx={4}
            fill="var(--sa-bg, #0f172a)"
            fillOpacity={0.92}
            stroke="var(--sa-border, #334155)"
            strokeWidth={1}
            style={{ pointerEvents: "none" }}
          />
          <text
            x={labelX}
            y={labelY + 4}
            textAnchor="middle"
            className="sa-traffic-edge-label"
          >
            {trafficLabel}
          </text>
        </>
      )}
      {isActive && (
        <circle r={4} className="sa-traffic-particle sa-traffic-particle-glow" style={{ pointerEvents: "none" }}>
          <animateMotion dur={`${duration}s`} repeatCount="indefinite" path={edgePath} />
        </circle>
      )}
    </>
  );
}

import { useMemo, useState, type ReactNode } from "react";
import { ChevronLeft, ChevronRight, Search } from "lucide-react";

export interface Column<T> {
  key: string;
  header: string;
  sortable?: boolean;
  render?: (row: T) => ReactNode;
  sortValue?: (row: T) => string | number;
}

interface DataTableProps<T> {
  columns: Column<T>[];
  data: T[];
  searchKeys?: (keyof T)[];
  searchPlaceholder?: string;
  pageSize?: number;
  onRowClick?: (row: T) => void;
  selectedId?: string | number | null;
  rowId?: (row: T) => string | number;
  emptyMessage?: string;
  loading?: boolean;
  toolbarLeading?: ReactNode;
}

function resolveRowId<T>(row: T, index: number, rowId?: (row: T) => string | number): string | number {
  if (typeof rowId === "function") return rowId(row);
  const id = (row as Record<string, unknown>).id;
  if (id != null) return id as string | number;
  return index;
}

export default function DataTable<T>({
  columns,
  data,
  searchKeys = [],
  searchPlaceholder = "Pesquisar...",
  pageSize = 10,
  onRowClick,
  selectedId,
  rowId,
  emptyMessage = "Nenhum registro encontrado.",
  loading = false,
  toolbarLeading,
}: DataTableProps<T>) {
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<"asc" | "desc">("asc");
  const [page, setPage] = useState(0);

  const filtered = useMemo(() => {
    let rows = data;
    if (search.trim()) {
      const q = search.toLowerCase();
      rows = rows.filter((row) =>
        searchKeys.some((key) => String(row[key] ?? "").toLowerCase().includes(q)),
      );
    }
    if (sortKey) {
      const col = columns.find((c) => c.key === sortKey);
      rows = [...rows].sort((a, b) => {
        const av = col?.sortValue ? col.sortValue(a) : String((a as Record<string, unknown>)[sortKey] ?? "");
        const bv = col?.sortValue ? col.sortValue(b) : String((b as Record<string, unknown>)[sortKey] ?? "");
        const cmp = av < bv ? -1 : av > bv ? 1 : 0;
        return sortDir === "asc" ? cmp : -cmp;
      });
    }
    return rows;
  }, [data, search, searchKeys, sortKey, sortDir, columns]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const paginated = filtered.slice(page * pageSize, (page + 1) * pageSize);

  function handleSort(key: string) {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
    setPage(0);
  }

  return (
    <div>
      {(toolbarLeading || searchKeys.length > 0) && (
        <div className="sa-table-toolbar">
          {toolbarLeading}
          {searchKeys.length > 0 && (
            <div className="sa-table-search-group">
              <div className="sa-table-search">
                <Search size={16} />
                <input
                  className="sa-input"
                  placeholder={searchPlaceholder}
                  value={search}
                  onChange={(e) => {
                    setSearch(e.target.value);
                    setPage(0);
                  }}
                />
              </div>
              <span className="sa-table-count">
                {filtered.length} registro{filtered.length !== 1 ? "s" : ""}
              </span>
            </div>
          )}
        </div>
      )}

      <div className="sa-table-wrap">
        <table className="sa-table">
          <thead>
            <tr>
              {columns.map((col) => (
                <th
                  key={col.key}
                  className={sortKey === col.key ? "sa-sorted" : undefined}
                  onClick={() => col.sortable !== false && handleSort(col.key)}
                >
                  {col.header}
                  {sortKey === col.key && (sortDir === "asc" ? " ↑" : " ↓")}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={columns.length} className="sa-empty">
                  <span className="sa-spinner" /> Carregando...
                </td>
              </tr>
            ) : paginated.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="sa-empty">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              paginated.map((row, index) => {
                const id = resolveRowId(row, index, rowId);
                return (
                  <tr
                    key={id}
                    className={selectedId === id ? "sa-row-selected" : undefined}
                    onClick={() => onRowClick?.(row)}
                    style={onRowClick ? { cursor: "pointer" } : undefined}
                  >
                    {columns.map((col) => (
                      <td key={col.key}>
                        {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? "—")}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>

        {filtered.length > pageSize && (
          <div className="sa-table-pagination">
            <span>
              Página {page + 1} de {totalPages}
              {" · "}
              {filtered.length} resultado{filtered.length === 1 ? "" : "s"}
            </span>
            <div className="sa-table-pagination-btns">
              <button
                type="button"
                className="sa-btn sa-btn-secondary sa-btn-sm sa-btn-icon"
                disabled={page === 0}
                onClick={() => setPage((p) => p - 1)}
              >
                <ChevronLeft size={16} />
              </button>
              <button
                type="button"
                className="sa-btn sa-btn-secondary sa-btn-sm sa-btn-icon"
                disabled={page >= totalPages - 1}
                onClick={() => setPage((p) => p + 1)}
              >
                <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

