  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: "welcome",
      role: "assistant",
      text: "Olá! Sou o NOC Copilot (DeepSeek/LLM). Pergunte sobre devices offline, alertas, anomalias ou peça um resumo operacional. Para ajuda sobre módulos do produto, use o Chatbot.",
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [llmSource, setLlmSource] = useState<string | null>(null);
