  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchCopilotContext()
      .then((ctx) => {
        setContext(ctx);
        setCtxPulse(true);
        window.setTimeout(() => setCtxPulse(false), 1200);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  const sendText = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || loading) return;
      setInput("");
      setMessages((m) => [...m, { id: newId(), role: "user", text: trimmed }]);
      setLoading(true);
      try {
        const res = await copilotChat(trimmed);
        setLlmSource(res.source ?? "rules-engine");
        setMessages((m) => [
          ...m,
          { id: newId(), role: "assistant", text: res.answer, actions: res.suggested_actions },
