            <span className="sa-copilot-stat-label">
              <Radio size={12} /> Offline
            </span>
            <strong className="sa-copilot-stat-value">{Number.isFinite(offline) ? offline : "—"}</strong>
            {offline > 0 && <span className="sa-copilot-stat-live" aria-hidden />}
          </div>
          <div className="sa-copilot-stat">
            <span className="sa-copilot-stat-label">Alertas pendentes</span>
            <strong className="sa-copilot-stat-value">{String(context.pending_alerts ?? "—")}</strong>
          </div>
          <div className="sa-copilot-stat">
            <span className="sa-copilot-stat-label">
              <Activity size={12} /> Anomalias
            </span>
            <strong className="sa-copilot-stat-value">{String(context.active_anomalies ?? "—")}</strong>
          </div>
        </div>
      )}

      <section className="sa-copilot-panel sa-card">
        <div className="sa-copilot-radar" aria-hidden>
          <span className="sa-copilot-radar-ring" />
          <span className="sa-copilot-radar-ring sa-copilot-radar-ring-2" />
          <span className="sa-copilot-radar-sweep" />
          <span className="sa-copilot-radar-grid" />
        </div>

        <div className="sa-card-header sa-copilot-header">
