function parseSummaryMetrics(summary: string) {
  const devices = summary.match(/(\d+)\s+dispositivos monitorados\s+\((\d+)\s+online,\s+(\d+)\s+offline\)/i);
  const avail = summary.match(/Disponibilidade estimada:\s*([\d.]+)%/i);
  const latency = summary.match(/Latência média:\s*([^\n.]+)/i);
  const events = summary.match(/Eventos registrados:\s*(\d+)\s+\((\d+)\s+críticos\)/i);
  const alerts = summary.match(/Alertas enviados:\s*(\d+)/i);
  const anomalies = summary.match(/Anomalias ativas:\s*(\d+)/i);
  return {
    total: devices ? Number(devices[1]) : null,
    online: devices ? Number(devices[2]) : null,
    offline: devices ? Number(devices[3]) : null,
    availability: avail ? Number(avail[1]) : null,
    latency: latency?.[1]?.trim() ?? null,
    events: events ? Number(events[1]) : null,
    criticalEvents: events ? Number(events[2]) : null,
    alertsSent: alerts ? Number(alerts[1]) : null,
    anomalies: anomalies ? Number(anomalies[1]) : null,
  };
}

